#!/usr/bin/env node
/**
 * Zero-dependency build: reads src/index.js (ES module, generated by
 * tools/generate.sh) and writes
 *   dist/esm/index.js      ES module
 *   dist/cjs/index.js      CommonJS
 *   dist/types/index.d.ts  TypeScript declarations
 */
import { readFileSync, writeFileSync, mkdirSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const ROOT = dirname(fileURLToPath(import.meta.url));
const src = readFileSync(join(ROOT, "src", "index.js"), "utf8");

// ── exported names (from the export { … } blocks) ────────────────────────────
const exportBlocks = [...src.matchAll(/^export \{([^}]*)\};?\s*$/gms)];
const names = exportBlocks.flatMap(m => m[1].split(",").map(s => s.trim()).filter(Boolean));
if (!names.length) throw new Error("src/index.js has no export { … } block");

const write = (rel, text) => {
  mkdirSync(dirname(join(ROOT, rel)), { recursive: true });
  writeFileSync(join(ROOT, rel), text, "utf8");
};

// ── ESM ──────────────────────────────────────────────────────────────────────
write("dist/esm/index.js", src);
write("dist/esm/package.json", JSON.stringify({ type: "module" }) + "\n");

// ── CJS ──────────────────────────────────────────────────────────────────────
let cjs = src.replace(/^export \{[^}]*\};?\s*$/gms, "");
cjs = `"use strict";\n${cjs.trimEnd()}\n\nmodule.exports = {\n${names.map(n => `  ${n},`).join("\n")}\n};\n`;
write("dist/cjs/index.js", cjs);
write("dist/cjs/package.json", JSON.stringify({ type: "commonjs" }) + "\n");

// ── TypeScript declarations ──────────────────────────────────────────────────
function splitTop(s) {
  const out = []; let depth = 0, cur = "";
  for (const ch of s) {
    if ("({[".includes(ch)) depth++;
    if (")}]".includes(ch)) depth--;
    if (ch === "," && depth === 0) { out.push(cur.trim()); cur = ""; continue; }
    cur += ch;
  }
  if (cur.trim()) out.push(cur.trim());
  return out;
}
function param(p, i) {
  if (p.startsWith("{")) {
    const inner = p.slice(1, p.lastIndexOf("}"));
    const keys = splitTop(inner).map(k => k.split("=")[0].trim()).filter(Boolean);
    return `options?: { ${keys.map(k => `${k}?: any;`).join(" ")} }`;
  }
  const [name, def] = p.split("=").map(s => s.trim());
  return `${name}${def !== undefined ? "?" : ""}: any`;
}
const classes = [];
for (const m of src.matchAll(/^class (\w+) extends (\w+) \{\}$/gm)) {
  classes.push({ name: m[1], base: m[2], members: [] });
}
const classRe = /^class (\w+)(?: extends (\w+))? \{\n(.*?)^\}/gms;
for (const m of src.matchAll(classRe)) {
  const [, name, base, body] = m;
  const members = [];
  for (const mm of body.matchAll(/^  (async )?(\w+)\((.*)\) \{$/gm)) {
    const [, isAsync, meth, params] = mm;
    if (meth.startsWith("_")) continue;
    const ps = splitTop(params).map(param).join(", ");
    if (meth === "constructor") members.push(`  constructor(${ps});`);
    else members.push(`  ${meth}(${ps}): ${meth === "close" ? "void" : "Promise<any>"};`);
  }
  classes.push({ name, base, members });
}
const extra = {
  OpenHABClient: [
    "  url: string;", "  username: string | null;", "  password: string | null;", "  token: string | null;",
    "  timeout: number;", "  isCloud: boolean;", "  isLoggedIn: boolean;",
    "  /** Resolves once the connection check is done (never rejects). */", "  ready: Promise<OpenHABClient>;",
  ],
  StatusResponse: ["  status: number;", "  location?: string;"],
  OpenHABHTTPError: ["  status: number;", "  url: string;", "  openhabMessage: string;", "  response: any;"],
};
let dts = `// Generated by build.js from src/index.js – do not edit.
// nodejs-openhab-rest-client: same classes and methods as python-openhab-rest-client.
// REST methods resolve to JSON, text, { message } or { error }.

`;
for (const c of classes) {
  if (!names.includes(c.name)) continue;
  const ext = c.base ? ` extends ${c.base}` : "";
  dts += `export declare class ${c.name}${ext} {\n${(extra[c.name] || []).concat(c.members).join("\n")}\n}\n\n`;
}
dts += `/** Yields the lines of a Server-Sent Events stream (a fetch Response). */
export declare function iterSSELines(response: any): AsyncGenerator<string>;
/** Yields the events of a Server-Sent Events stream with decoded payload. */
export declare function iterSSEEvents(response: any, includeAlive?: boolean): AsyncGenerator<any>;
/** Decodes one "data:" line. */
export declare function parseSSEData(line: string): any;
export declare const aiterSSELines: typeof iterSSELines;
export declare const aiterSSEEvents: typeof iterSSEEvents;
`;
write("dist/types/index.d.ts", dts);
// per-format copies so that TypeScript ("moduleResolution": "node16"/"nodenext") resolves ESM and CJS
write("dist/esm/index.d.ts", dts);
write("dist/cjs/index.d.ts", dts);

console.log(`✓ dist/esm, dist/cjs, dist/types (${names.length} exports, ${classes.length} classes)`);
